package br.com.sussmartcare.queue.infrastructure.messaging; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="pending_queue_priorities") public class PendingQueuePriority{@Id private UUID visitId;@Column(nullable=false)private String priority;@Column(nullable=false)private Instant receivedAt;protected PendingQueuePriority(){}public PendingQueuePriority(UUID v,String p){visitId=v;priority=p;receivedAt=Instant.now();}public String getPriority(){return priority;}}